// ---- geometry -------------------------------------------------------
// A box: centre x/z, bottom y, size L(x)×H(y)×W(z), optional yaw about vertical.
function faceBox(cx, by, cz, L, H, W, yawDeg = 0) {
  const x = L / 2;
  const z = W / 2;
  const y0 = by;
  const y1 = by + H;
  const yaw = (yawDeg * Math.PI) / 180;
  const cs = Math.cos(yaw);
  const sn = Math.sin(yaw);
  const P = (lx, ly, lz) => [cx + (lx * cs - lz * sn), ly, cz + (lx * sn + lz * cs)];
  const RN = (n) => [n[0] * cs - n[2] * sn, n[1], n[0] * sn + n[2] * cs];
  const faces = [
    { n: [0, 1, 0], v: [P(-x, y1, -z), P(x, y1, -z), P(x, y1, z), P(-x, y1, z)] },
    { n: [0, -1, 0], v: [P(-x, y0, z), P(x, y0, z), P(x, y0, -z), P(-x, y0, -z)] },
    { n: [0, 0, 1], v: [P(-x, y0, z), P(-x, y1, z), P(x, y1, z), P(x, y0, z)] },
    { n: [0, 0, -1], v: [P(x, y0, -z), P(x, y1, -z), P(-x, y1, -z), P(-x, y0, -z)] },
    { n: [1, 0, 0], v: [P(x, y0, z), P(x, y1, z), P(x, y1, -z), P(x, y0, -z)] },
    { n: [-1, 0, 0], v: [P(-x, y0, -z), P(-x, y1, -z), P(-x, y1, z), P(-x, y0, z)] },
  ];
  const pos = [];
  const nrm = [];
  const idx = [];
  faces.forEach((f, fi) => {
    const rn = RN(f.n);
    f.v.forEach((p) => {
      pos.push(...p);
      nrm.push(...rn);
    });
    const b = fi * 4;
    idx.push(b, b + 1, b + 2, b, b + 2, b + 3);
  });
  return { pos, nrm, idx };
}

/** wheel-set helper: four boxes at ±halfTrack / ±wheelBase */
function wheels(wheelBase, halfTrack, r, w) {
  const out = [];
  for (const sx of [1, -1]) for (const sz of [1, -1]) {
    out.push({ box: [sx * wheelBase, 0, sz * halfTrack, r * 2, r * 1.6, w], col: C.tyre });
  }
  return out;
}

