// ---- model builder -------------------------------------------------
function modelGltf(name, parts, fx = []) {
  const groups = new Map();
  for (const p of parts) {
    // key on the full surface, not just colour — two parts sharing a colour but
    // differing in glow or transparency need their own material.
    const key = `${p.col.join(',')}|${p.emit ?? 0}|${p.alpha ?? 1}`;
    if (!groups.has(key))
      groups.set(key, { col: p.col, emit: p.emit, alpha: p.alpha, pos: [], nrm: [], idx: [] });
    const g = groups.get(key);
    const base = g.pos.length / 3;
    const b = faceBox(...p.box);
    for (const v of b.pos) g.pos.push(v);
    for (const v of b.nrm) g.nrm.push(v);
    for (const i of b.idx) g.idx.push(i + base);
  }

  const pad = (buf) => (buf.length % 4 ? Buffer.concat([buf, Buffer.alloc(4 - (buf.length % 4))]) : buf);
  const bins = [];
  const bufferViews = [];
  const accessors = [];
  const materials = [];
  const primitives = [];
  let off = 0;
  let mi = 0;

  for (const g of groups.values()) {
    const posBuf = pad(Buffer.from(new Float32Array(g.pos).buffer));
    const nrmBuf = pad(Buffer.from(new Float32Array(g.nrm).buffer));
    const idxBuf = pad(Buffer.from(new Uint16Array(g.idx).buffer));

    const posView = bufferViews.length;
    bufferViews.push({ buffer: 0, byteOffset: off, byteLength: g.pos.length * 4, target: 34962 });
    off += posBuf.length;
    const nrmView = bufferViews.length;
    bufferViews.push({ buffer: 0, byteOffset: off, byteLength: g.nrm.length * 4, target: 34962 });
    off += nrmBuf.length;
    const idxView = bufferViews.length;
    bufferViews.push({ buffer: 0, byteOffset: off, byteLength: g.idx.length * 2, target: 34963 });
    off += idxBuf.length;
    bins.push(posBuf, nrmBuf, idxBuf);

    const mn = [1e9, 1e9, 1e9];
    const mx = [-1e9, -1e9, -1e9];
    for (let i = 0; i < g.pos.length; i += 3)
      for (let k = 0; k < 3; k++) {
        mn[k] = Math.min(mn[k], g.pos[i + k]);
        mx[k] = Math.max(mx[k], g.pos[i + k]);
      }

    const posAcc = accessors.length;
    accessors.push({ bufferView: posView, componentType: 5126, count: g.pos.length / 3, type: 'VEC3', min: mn, max: mx });
    const nrmAcc = accessors.length;
    accessors.push({ bufferView: nrmView, componentType: 5126, count: g.nrm.length / 3, type: 'VEC3' });
    const idxAcc = accessors.length;
    accessors.push({ bufferView: idxView, componentType: 5123, count: g.idx.length, type: 'SCALAR' });

    // `emit` makes a surface self-lit (flame, beacon) so it still reads at dusk
    // and at night, when a plain diffuse orange box goes black. `alpha` turns a
    // part translucent (smoke) instead of a solid grey slab.
    const alpha = g.alpha ?? 1;
    const mat = {
      name: `${name}_m${mi}`,
      pbrMetallicRoughness: {
        baseColorFactor: [...g.col, alpha],
        metallicFactor: 0,
        roughnessFactor: g.emit ? 1 : 0.85,
      },
      doubleSided: true,
    };
    if (g.emit) mat.emissiveFactor = g.col.map((c) => Math.min(1, c * g.emit));
    if (alpha < 1) mat.alphaMode = 'BLEND';
    materials.push(mat);
    primitives.push({ attributes: { POSITION: posAcc, NORMAL: nrmAcc }, indices: idxAcc, material: mi, mode: 4 });
    mi++;
  }

  const bin = Buffer.concat(bins);
  const gltf = {
    asset: { version: '2.0', generator: 'AED model builder', minVersion: '2.0' },
    extensionsUsed: [],
    extensionsRequired: [],
    scene: 0,
    scenes: [{ nodes: [0, ...fx.map((_, i) => i + 1)] }],
    // The mesh, then one empty node per effect. ASOBO_GT_FX attaches to a node
    // by name, so these exist purely as attach points.
    nodes: [{ mesh: 0, name }, ...fx.map((f) => ({ name: f.node, translation: f.at ?? [0, 0, 0] }))],
    meshes: [{ name, primitives }],
    materials: materials.map((m) => ({ alphaMode: 'OPAQUE', ...m })),
    buffers: [{ uri: `${name}.bin`, byteLength: bin.length }],
    bufferViews,
    accessors,
  };
  return { gltf: JSON.stringify(gltf, null, 1), bin };
}

// ---- models -------------------------------------------------------
// Convention: +x forward, +y up, +z right; the object sits on y = 0.

function sedan(bodyCol, extras = []) {
  return [
    { box: [0, 0.24, 0, 4.4, 0.72, 1.78], col: bodyCol },
    { box: [-0.25, 0.94, 0, 2.4, 0.6, 1.6], col: bodyCol },
    { box: [0.92, 0.95, 0, 0.14, 0.55, 1.5], col: C.glass }, // windscreen
    { box: [-1.4, 0.95, 0, 0.12, 0.5, 1.46], col: C.glass }, // rear glass
    ...wheels(1.4, 0.85, 0.34, 0.28),
    ...extras,
  ];
}

